stock = {'pommes': 50, 'bananes': 30, 'lait': 20, 'pain': 15}

while True:
    print("\n--- Gestion de Stock ---")
    print("1. Afficher le stock")
    print("2. Ajouter un produit")
    print("3. Vendre un produit")
    print("4. Quitter")
    choix = input("Votre choix : ")

    if choix == '1':
        for produit, quantite in stock.items():
            print(f"{produit}: {quantite}")

    elif choix == '2':
        produit = input("Nom du produit à ajouter : ").lower()
        try:
            quantite = int(input("Quantité à ajouter : "))
            if quantite <= 0:
                print("La quantité doit être positive.")
                continue
            if produit in stock:
                stock[produit] += quantite
            else:
                stock[produit] = quantite
            print(f"Stock mis à jour. {produit} : {stock[produit]}")
        except ValueError:
            print("Quantité invalide. Veuillez entrer un nombre.")

    elif choix == '3':
        produit = input("Nom du produit à vendre : ").lower()
        if produit not in stock:
            print("Produit non trouvé.")
            continue
        try:
            quantite = int(input("Quantité à vendre : "))
            if quantite <= 0:
                print("La quantité doit être positive.")
                continue
            if quantite > stock[produit]:
                print(f"Stock insuffisant. Il ne reste que {stock[produit]} {produit}.")
            else:
                stock[produit] -= quantite
                print(f"Vente effectuée. Nouveau stock de {produit} : {stock[produit]}")
                if stock[produit] == 0:
                    del stock[produit]  # Optionnel: retirer le produit si stock nul
        except ValueError:
            print("Quantité invalide. Veuillez entrer un nombre.")

    elif choix == '4':
        print("Au revoir !")
        break

    else:
        print("Choix invalide. Veuillez choisir 1, 2, 3 ou 4.")
```
